//! The partner point template — the host glue. ⛔ Do not edit this file: write your function in `point.rs`.
//!
//! The host contract (`tools/wasm_kit/CONTRACT.md`, from `HOST_CONTRACT.md` §5): the native profile `pp` —
//! three imports (`read_input`, `write_output`, `log`), one export `run() -> i32`. Input and output are UTF-8 JSON.
//! No clock, no randomness, no float, no network: there is nothing to import them from.

mod json;
pub mod point;

/// The whole point, as the hosts and the tests call it: input bytes in, output bytes out. Never panics on any input.
pub fn answer(input: &[u8]) -> Vec<u8> {
    let out = match json::parse(input) {
        Ok(v) => point::decide(&v),
        Err(()) => Err("input".to_string()),
    };
    match out {
        Ok(v) => json::write(&v).into_bytes(),
        Err(at) => {
            json::write(&json::obj(vec![("error", json::s("invalid_input")), ("at", json::s(&at))])).into_bytes()
        }
    }
}

#[cfg(target_arch = "wasm32")]
mod glue {
    #[link(wasm_import_module = "pp")]
    extern "C" {
        fn read_input(ptr: *mut u8, len: u32) -> u32;
        fn write_output(ptr: *const u8, len: u32);
        fn log(ptr: *const u8, len: u32);
    }

    #[no_mangle]
    pub extern "C" fn run() -> i32 {
        let total = unsafe { read_input(core::ptr::null_mut(), 0) } as usize;
        let mut buf = vec![0u8; total];
        unsafe { read_input(buf.as_mut_ptr(), total as u32) };
        let out = super::answer(&buf);
        unsafe { write_output(out.as_ptr(), out.len() as u32) };
        let note = b"pp_point: done";
        unsafe { log(note.as_ptr(), note.len() as u32) };
        0
    }
}
